def _rows_to_families(rows):
    families = {}
    topics = {"backend_python": "Python для Backend", "sql": "SQL и работа с данными",
              "api": "HTTP API и интеграция", "reliability": "Надёжность сервиса"}
    for code, skill_code, skill, source, options, prompts, explanation in rows:
        assert len(options) == 4 and len(prompts) == 3
        families[code] = {
            "topic": topics[skill_code], "skill": skill,
            "rubric": explanation, "source_url": SOURCES[source],
            "options": list(options),
            "cases": [
                (prompt if isinstance(prompt, str) else prompt[0],
                 0 if isinstance(prompt, str) else prompt[1], explanation)
                for prompt in prompts
            ],
        }
    return families


